function OnHit($player, $mzID, $amount) {
    if(FaBSUPGallowStops(intval($player)))return 0;
    $params = compact('mzID', 'amount'); $found = FaBIdentityFromMZ((string)$mzID);
    if($found!==null&&FaBHasType($found['object'],'Dagger')){$s=FaBGetState();$s['daggerHits']=intval($s['daggerHits']??0)+1;FaBSetState($s);}
    if($found!==null&&FaBFaiHeroHit())FaBHNTBeforeHit(intval($player),$found['object'],intval(FaBGetState()['defender']));
    if($found!==null)FaBHNTAnyHit(intval($player),$found['object']);
    if($found!==null)FaBOUTSuppressHit($found['object']);
    if ($found !== null && function_exists('FaBWTRHit')) FaBWTRHit(intval($player), $found['object'], intval($amount));
    if($found!==null&&FaBCRUHitSuppressed($found['object'],true))return 0;
    if($found!==null){FaBIARHit(intval($player),$found['object']);FaBOMNHit(intval($player),$found['object']);FaBSUPHit(intval($player),$found['object']);FaBPENHit(intval($player));FaBMPGHit(intval($player),$found['object'],intval($amount));FaBSEAHit(intval($player),$found['object'],intval($amount));FaBCRUHit(intval($player),$found['object'],intval($amount));FaBMONHit(intval($player),$found['object']);FaBELEHit(intval($player),$found['object'],intval($amount));FaBEVRHit(intval($player),$found['object'],intval($amount));FaBDYNHit(intval($player),$found['object'],intval($amount));FaBOUTHit(intval($player),$found['object'],intval($amount));FaBDTDHit(intval($player),$found['object'],intval($amount));FaBEVOHit(intval($player),$found['object'],intval($amount));FaBHVYHit(intval($player),$found['object'],intval($amount));FaBMSTHit(intval($player),$found['object']);FaBROSHit(intval($player),$found['object']);if(FaBFaiHeroHit())FaBHNTHit(intval($player),$found['object'],intval(FaBGetState()['defender']));FaBEVRFractalDispatch(intval($player),$found['object'],'Hit',['mzID'=>$mzID,'amount'=>$amount]);if(intval($amount)>0)FaBBoltynHit(intval($player));}
    // Effects such as Seek Enlightenment can move the attack before its own hit ability.
    if($found!==null){$live=FaBFindUID(intval($found['object']->UniqueID));if($live!==null)$params['mzID']=$live['mzID'];}
    $count = $found === null || FaBCRUHitSuppressed($found['object']) ? 0 : FaBRunSourceMacro('Hit', intval($player), $found['object']->CardID, $params);
    $count += function_exists('DispatchMacroListeners') ? DispatchMacroListeners('Hit', intval($player), $params) : 0;
    if ($found !== null) FaBARCAfterHit(intval($player), $found['object'], intval($amount));
    if($found!==null&&in_array('WTR_RETURN_HAND',(array)$found['object']->TurnEffects,true)){
        $state=FaBGetState();$state['attackGoAgain']=FaBAttackHasGoAgain($state,$found['object']);FaBSetState($state);
        FaBMoveUID(intval($found['object']->UniqueID),'Hand',intval($player));
    }
    return $count;
}

function FaBRunSourceMacro(string $macroName, int $player, string $cardID, array $params): int {
    $sourceRef=FaBIdentityFromMZ((string)($params['mzID']??''));
    $grantedBoost=$sourceRef&&FaBARCGrantedBoostMacro($sourceRef['object'],$macroName,$player,$cardID,$params);
    if($sourceRef&&!$grantedBoost&&(FaBMPGSuppressed($sourceRef['object'])||FaBSUPSuppressed($sourceRef['object']))){if($macroName==='PrepareCard'){FaBFinishPreparedCard(intval($sourceRef['object']->UniqueID));return 1;}if(!str_ends_with($macroName,'Modifier'))return 1;}
    $countFn = 'Card' . $macroName . 'Count';
    $base = lcfirst($macroName);
    $abilities = $GLOBALS[$base . 'Abilities'] ?? [];
    $prereqs = $GLOBALS[$base . 'Prereqs'] ?? [];
    if (!function_exists($countFn) || !is_array($abilities)) return 0;
    foreach ($params as $name => $value) DecisionQueueController::StoreVariable($name, $value);
    $ran = 0;
    for ($i = 0; $i < intval($countFn($cardID)); ++$i) {
        $key = $cardID . ':' . $i;
        if (!isset($abilities[$key])) continue;
        if (isset($prereqs[$key]) && !$prereqs[$key](...array_merge([$player], array_values($params)))) continue;
        $previousEffect=$GLOBALS['fabEffectController']??0;$GLOBALS['fabEffectController']=$player;
        try {$abilities[$key]($player); ++$ran;} finally {$GLOBALS['fabEffectController']=$previousEffect;}
    }
    return $ran;
}

/** Generated await continuations must receive PASS as a return value. */

function FaBHVYToken(int $p,string $id,int $n=1,?int $controller=null,?bool $action=null,bool $wager=false): ?object {
    if(!FaBSeatIsLive($p)||$n<1)return null;$controller??=intval($GLOBALS['fabEffectController']??0)?:$p;$action??=FaBHVYActionSource();
    if(FaBPENReplaceFrost($p,$id,$n,$controller,$action,$wager))return null;
    $n=FaBMPGTokenCount($p,$id,$n);if(FaBHasType($id,'Aura') && (FaBHasType($id,'Elemental')||FaBHasType($id,'Runeblade')))$n+=FaBARCEffect($p,'PEN_VERDANT');if($n<1)return null;
    if(FaBHasType($id,'Aura')&&FaBROSActive($p,'florian'))++$n;
    if($wager)foreach(FaBLiveSeats() as $s)$n+=FaBHVYCount($s,'DOUBLE_DOWN');
    if($action)foreach(FaBLiveSeats() as $s)$n-=FaBHVYCount($s,'RIPPLE');
    $first=null;for($i=0;$i<max(0,$n);++$i){$o=FaBWTRCreateArena($p,$id,true);$first??=$o;}
    if($n>0&&$id==='runechant')FaBIARCreatedRunes($p,$n);
    if($n>0&&in_array($id,['agility','confidence','toughness','might','vigor'],true))FaBHVYAdd($p,'CONTROLLED_'.$id);
    if($n>0&&$id==='gold'&&$controller===$p&&FaBHVYHero($p,'victor_goldmane')&&!FaBHVYCount($p,'VICTOR_DRAW')&&in_array(GetCurrentPhase(),['MAIN','END'],true)) {
        FaBHVYAdd($p,'VICTOR_DRAW');DoDrawCard($p,1);
    }
    return $first;
}

function FaBWTRQueueDrawOnHit(int $player, object $attack): void {
    if (!FaBSeatIsLive($player) || HasNoAbilities($attack)) return;
    $state = FaBGetState();
    AddStack(CardID:$attack->CardID, Owner:$player, Controller:$player, Kind:'ABILITY',
        SourceZone:'CombatChain', SourceUniqueID:intval($attack->UniqueID),
        Params:['wtrDrawTrigger'=>true, 'returnWindow'=>(string)$state['window'],
            'returnCombatStep'=>(string)$state['combatStep']]);
    $state = FaBGetState(); $state['window'] = 'PRIORITY'; FaBSetState($state);
}

/** Queue the play trigger; its conditional grant is evaluated on resolution. */

function FaBELEPlayed(int $p,object $o,string $from): void {
    if(!FaBWTRIsWeapon($o))foreach(FaBMONArena($p,'frostbite') as $r)FaBMONDestroy(intval(FaBIdentityFromMZ($r)['object']->UniqueID));
    if(!FaBHasType($o,'Action')&&!FaBWTRIsWeapon($o))return;
    $b=FaBWTRBase($o->CardID);$uid=intval($o->UniqueID);$aa=FaBWTRIsAttackAction($o);$attack=$aa||FaBWTRIsWeapon($o);
    if(FaBHasType($o,'Action')){if(FaBELECount($p,'NEXT_ACTION_GO')){FaBWTRTag($o,'GO_AGAIN');FaBELEClear($p,'NEXT_ACTION_GO');}
        if(!$aa)FaBELEClear($p,'NEXT_INSTANT');
        foreach(FaBMONArena($p,'channel_thunder_steppe') as $r)FaBRunSourceMacro('ResolveAbility',$p,'channel_thunder_steppe_yellow',['mzID'=>$r,'eleActionUID'=>$uid]);
    }
    if($aa){foreach(FaBMONArena($p,'embodiment_of_lightning') as $r){FaBWTRTag($o,'GO_AGAIN');FaBMONDestroy(intval(FaBIdentityFromMZ($r)['object']->UniqueID));}}
    if(FaBWTRHeroActive($p)&&in_array((GetHero($p)[0]->CardID??''),['briar','briar_warden_of_thorns'],true)&&!$aa&&FaBHasType($o,'Action')&&count(FaBARCPlayed($p,true))===2)FaBWTRCreateArena($p,'embodiment_of_lightning');
    $left=[];foreach(FaBWTREffects($p) as $e){$k=$e['type']??'';$use=false;$v=intval($e['amount']??0);
        if($attack&&$k==='ELE_NEXT_ATTACK')$use=true;
        if($aa&&$k==='ELE_NEXT_AA')$use=true;
        if($attack&&$k==='ELE_NEXT_ELEMENT'&&FaBELEElement($o,'Earth|Ice|Lightning|Elemental'))$use=true;
        if($attack&&$k==='ELE_NEXT_GUARDIAN'&&FaBHasType($o,'Guardian'))$use=true;
        if($attack&&$k==='ELE_NEXT_ARROW'&&FaBHasType($o,'Arrow'))$use=true;
        if($attack&&$k==='ELE_NEXT_FUSED'&&FaBELEFused($uid))$use=true;
        if($aa&&str_starts_with($k,'ELE_WEAVE_')&&FaBELEElement($o,substr($k,10).'|Elemental')){$use=true;if(FaBELEFused($uid)){if($k==='ELE_WEAVE_Earth')++$v;if($k==='ELE_WEAVE_Ice')FaBWTRTag($o,'DOMINATE');if($k==='ELE_WEAVE_Lightning')FaBWTRTag($o,'GO_AGAIN');}}
        if(!$use){$left[]=$e;continue;}if($v)FaBWTRTag($o,'WTR_POWER:'.$v);foreach($e['tags']??[] as $tag)FaBWTRTag($o,$tag);
    }FaBWTRSetEffects($p,$left);
    if($from==='Arsenal'){if($b==='burgeoning'&&!HasNoAbilities($o))FaBWTRTag($o,'WTR_POWER:1');if($b==='lightning_surge')FaBWTRTag($o,'GO_AGAIN');if($b==='evergreen')FaBWTRTag($o,'ELE_BOTTOM_CLOSE');}
    if($attack&&FaBELECount($p,'ENTANGLE')){FaBWTRTag($o,'WTR_POWER:-2');FaBELEClear($p,'ENTANGLE');}
}

function FaBELEStart(int $p): void {
    foreach(FaBChoiceRefs($p,'Arena') as $r){$o=FaBIdentityFromMZ($r)['object'];$b=FaBWTRBase($o->CardID);
        if(in_array($b,['embodiment_of_earth','embolden','emerging_avalanche','strength_of_sequoia'],true)){
            if($b!=='embodiment_of_earth')FaBWTRAddEffect($p,$b==='embolden'?'NEXT_GUARDIAN':'NEXT_ATTACK',FaBWTRPitchValue($o->CardID,$b==='embolden'?[5,4,3]:[3,2,1]));
            FaBMONDestroy(intval($o->UniqueID));
        }
    }
}
